 for r in select * from jsonb_to_recordset(p_payload->'rows')as x(placement_key text,affiliate_url text,observed_at timestamptz,account_active boolean,relationship_joined boolean,terms_active boolean,pid_generated boolean,target_country_match boolean)loop
  v_url:=nullif(btrim(r.affiliate_url),'');v_host:=lower(substring(v_url from '^https://([^/:?#]+)'));if v_url is null or v_host is null or v_host<>all(array['www.anrdoezrs.net','www.dpbolvw.net','www.jdoqocy.com','www.kqzyfj.com','www.tkqlhce.com']) or v_url!~'^https://www\.(anrdoezrs\.net|dpbolvw\.net|jdoqocy\.com|kqzyfj\.com|tkqlhce\.com)/click-[0-9]+-[0-9]+' or r.observed_at<clock_timestamp()-interval '24 hours' or r.observed_at>clock_timestamp()+interval '5 minutes' or not coalesce(r.account_active,false)or not coalesce(r.relationship_joined,false)or not coalesce(r.terms_active,false)or not coalesce(r.pid_generated,false)or not coalesce(r.target_country_match,false)then raise exception 'v3370 CJ row failed validation';end if;
  update public.nexus_v3370_cj_placement_policy set affiliate_url_enc=extensions.pgp_sym_encrypt(v_url,v_kms,'cipher-algo=aes256,compress-algo=1'),affiliate_host_sha256=encode(extensions.digest(v_host,'sha256'),'hex'),evidence_observed_at=r.observed_at,evidence_expires_at=r.observed_at+interval '24 hours',route_enabled=true,activation_reason='fresh_encrypted_cj_link_installed',updated_at=clock_timestamp()where placement_key=r.placement_key;if not found then raise exception 'v3370 unknown placement';end if;v_seen:=v_seen+1;v_url:=null;v_host:=null;
 end loop;if v_seen<>7 or(select count(*)from public.nexus_v3370_cj_placement_policy where route_enabled and affiliate_url_enc is not null)<>7 then raise exception 'v3370 hydration count';end if;
 insert into public.nexus_v3000_capability_registry(capability,enabled,evidence,checked_at)values('v3370_au_cj_routes',true,jsonb_build_object('enabled_routes',7,'fresh_encrypted_payload',true,'plaintext_returned',false),clock_timestamp())on conflict(capability)do update set enabled=excluded.enabled,evidence=excluded.evidence,checked_at=excluded.checked_at;v_kms:=null;v_url:=null;v_host:=null;p_payload:=null;return jsonb_build_object('version','v3370.0','installed',7,'encrypted',true,'plaintext_returned',false);exception when others then v_kms:=null;v_url:=null;v_host:=null;p_payload:=null;raise;end;end
$function$;
revoke all on function public.nexus_v3370_hydrate_cj(jsonb)from public,anon,authenticated,service_role;grant execute on function public.nexus_v3370_hydrate_cj(jsonb)to service_role;
do $hydrate_from_guc$ declare v_payload jsonb;begin begin v_payload:=nullif(current_setting('nexus.v3370_cj_links_json',true),'')::jsonb;if v_payload is not null then perform public.nexus_v3370_hydrate_cj(v_payload);end if;perform set_config('nexus.v3370_cj_links_json','',true);v_payload:=null;exception when others then perform set_config('nexus.v3370_cj_links_json','',true);v_payload:=null;raise;end;end $hydrate_from_guc$;

create or replace function public.nexus_v3370_resolve_city(p_headers jsonb,p_destination text,p_admin_area text,p_locale text,p_intent_text text,p_user_supplied_destination boolean)returns jsonb language plpgsql security definer set search_path='public','extensions','pg_temp' as $function$
declare v_country text;v_key text;v_admin text;v_text text;v_intent text;v_count integer;v_copy text;v_source text;r public.nexus_v3370_city_delta%rowtype;p record;begin perform set_config('statement_timeout','2000',true);perform set_config('lock_timeout','1000',true);begin
 if p_headers is null or jsonb_typeof(p_headers)<>'object' or p_user_supplied_destination is not true then return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','trusted_user_query_context_required','affiliate_url',null);end if;
 select upper(btrim(e.value))into v_country from jsonb_each_text(p_headers)e where lower(e.key)in('cf-ipcountry','x-vercel-ip-country')and btrim(e.value)<>'' order by case lower(e.key)when'cf-ipcountry'then 0 else 1 end limit 1;
 if v_country is null or v_country!~'^[A-Z]{2}$'or v_country in('XX','T1')then return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','cdn_country_unavailable','affiliate_url',null,'human_or_residential_proven',false);end if;
 if p_destination is null or length(btrim(p_destination))not between 2 and 120 or p_intent_text is null or length(btrim(p_intent_text))not between 3 and 500 then return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','payload_invalid','affiliate_url',null);end if;
 v_key:=public.nexus_v3370_norm(p_destination);v_admin:=public.nexus_v3370_norm(coalesce(p_admin_area,''));v_text:=public.nexus_v3370_norm(p_intent_text);
 select count(*)into v_count from public.nexus_v3370_city_delta c where c.routing_country_code=v_country and(c.destination_key=v_key or exists(select 1 from unnest(c.aliases)a where public.nexus_v3370_norm(a)=v_key))and(v_admin=''or public.nexus_v3370_norm(c.admin_area)=v_admin or public.nexus_v3370_norm(coalesce(c.validated_admin_area,''))=v_admin);
 if v_count=0 then return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','destination_not_in_v3370_delta','country',v_country,'affiliate_url',null);end if;if v_count>1 then return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','admin_area_required_for_ambiguous_destination','country',v_country,'matches',v_count,'affiliate_url',null);end if;
 select * into r from public.nexus_v3370_city_delta c where c.routing_country_code=v_country and(c.destination_key=v_key or exists(select 1 from unnest(c.aliases)a where public.nexus_v3370_norm(a)=v_key))and(v_admin=''or public.nexus_v3370_norm(c.admin_area)=v_admin or public.nexus_v3370_norm(coalesce(c.validated_admin_area,''))=v_admin)limit 1;
 if not r.routing_eligible then return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','destination_validated_but_routing_disabled','country',v_country,'destination',r.destination_name,'affiliate_url',null);end if;if r.admin_required_for_disambiguation and v_admin=''then return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','admin_area_required_for_ambiguous_destination','country',v_country,'destination',r.destination_name,'affiliate_url',null);end if;
 if p_locale is null or not exists(select 1 from unnest(r.locale_codes)l where lower(l)=lower(btrim(p_locale)))then return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','locale_not_supported','country',v_country,'supported_locales',r.locale_codes,'affiliate_url',null);end if;
 v_intent:=case when v_text~'(^| )(hotel|hotels|hotelaria|hoteles)( |$)'then'hotel' when v_text~'(^| )(flight|flights|voo|voos|vuelo|vuelos|penerbangan)( |$)'then'flight' when v_text~'(^| )(car rental|rent a car|aluguel de carro|alquiler de auto|renta de auto|sewa mobil)( |$)'then'car_rental' when v_text~'(^| )(attraction|attractions|atraccion|atracciones)( |$)'then'attractions' when v_text~'(^| )(vacation|holiday|vacaciones|liburan)( |$)'then'vacation' when v_text~'(^| )(travel|trip|viagem|viaje|viajes|perjalanan|wisata)( |$)'then'travel' else null end;
 if v_intent is null then return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','travel_intent_not_explicit','country',v_country,'destination',r.destination_name,'affiliate_url',null);end if;
 if v_country='AU'then select q.* into p from public.nexus_v3370_cj_placement_policy q where q.country_code=v_country and lower(q.locale)=lower(p_locale)and q.intent in(v_intent,'travel')and q.route_enabled and q.affiliate_url_enc is not null and q.evidence_expires_at>clock_timestamp()and(q.promotion_start_date is null or q.promotion_start_date<=clock_timestamp())and(q.promotion_end_date is null or q.promotion_end_date>clock_timestamp())and(q.terms_end_time is null or q.terms_end_time>clock_timestamp())order by(q.intent=v_intent)desc,q.mobile_optimized desc,q.advertiser_name,q.link_id limit 1;v_source:='v3370';
 elsif v_country in('GB','IN')and v_intent<>'attractions'then select q.* into p from public.nexus_v3360_cj_placement_policy q where q.country_code=v_country and lower(q.locale)=lower(p_locale)and q.intent in(v_intent,'travel')and q.route_enabled and q.affiliate_url_enc is not null and q.evidence_expires_at>clock_timestamp()and(q.promotion_start_at is null or q.promotion_start_at<=clock_timestamp())and(q.promotion_end_at is null or q.promotion_end_at>clock_timestamp())and(q.terms_end_at is null or q.terms_end_at>clock_timestamp())order by(q.intent=v_intent)desc,q.mobile_optimized desc,q.advertiser_name,q.link_id limit 1;v_source:='v3360';else return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','fresh_encrypted_affiliate_route_unavailable','country',v_country,'destination',r.destination_name,'locale',p_locale,'intent',v_intent,'affiliate_url',null,'country_target_is_city_serviceability_proof',false);end if;
 if p.placement_key is null then return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','fresh_encrypted_affiliate_route_unavailable','country',v_country,'destination',r.destination_name,'locale',p_locale,'intent',v_intent,'affiliate_url',null,'country_target_is_city_serviceability_proof',false);end if;
 v_copy:=case when lower(p_locale)='es-mx'then'Compara opciones para tu viaje y confirma disponibilidad, precio, cobertura y condiciones directamente con el socio.'when lower(p_locale)='id-id'then'Bandingkan opsi perjalanan dan konfirmasikan ketersediaan, harga, cakupan, dan ketentuan langsung dengan mitra.'else'Compare travel options and confirm availability, price, coverage and terms directly with the partner.'end;
 return jsonb_build_object('version','v3370.0','estado','ok','country',v_country,'destination',r.destination_name,'admin_area',r.admin_area,'locale',p_locale,'intent',v_intent,'copy',v_copy,'disclosure_required_before_link','#ad','disclosure_own_line',true,'placement_key',p.placement_key,'policy_source',v_source,'affiliate_url',null,'redirect_performed',false,'click_recorded',false,'impression_recorded',false,'sale_claimed',false,'city_inferred_from_cdn',false,'human_or_residential_proven',false,'country_target_is_city_serviceability_proof',false);
 exception when others then return jsonb_build_object('version','v3370.0','estado','Sintonizado em Análise','motivo','resolver_exception','affiliate_url',null);end;end
$function$;
revoke all on function public.nexus_v3370_resolve_city(jsonb,text,text,text,text,boolean)from public,anon,authenticated,service_role;grant execute on function public.nexus_v3370_resolve_city(jsonb,text,text,text,text,boolean)to service_role;
create or replace function public.nexus_v3370_operator_status()returns jsonb language sql stable security definer set search_path='public','extensions','pg_temp' as $function$ select jsonb_build_object('version','v3370.0','city_delta',jsonb_build_object('rows',(select count(*)from public.nexus_v3370_city_delta),'routing_eligible',(select count(*)from public.nexus_v3370_city_delta where routing_eligible),'disabled',(select count(*)from public.nexus_v3370_city_delta where not routing_eligible)),'cj',jsonb_build_object('au_policy_rows',(select count(*)from public.nexus_v3370_cj_placement_policy),'au_enabled_routes',(select count(*)from public.nexus_v3370_cj_placement_policy where route_enabled and evidence_expires_at>clock_timestamp()),'inherited_gb_in_routes',(select count(*)from public.nexus_v3360_cj_placement_policy where country_code in('GB','IN')and route_enabled and evidence_expires_at>clock_timestamp()),'mx_routes',0,'id_routes',0,'affiliate_url_returned',false),'publication',jsonb_build_object('city_pages_published',false,'seo_indexing_enabled',false,'redirect_endpoint_deployed',false),'effects',jsonb_build_object('clicks_performed',false,'impressions_created',false,'sales_claimed',false));$function$;
revoke all on function public.nexus_v3370_operator_status()from public,anon,authenticated,service_role;grant execute on function public.nexus_v3370_operator_status()to service_role;
insert into public.nexus_v3000_capability_registry(capability,enabled,evidence,checked_at)values('v3370_city_delta',true,jsonb_build_object('source_rows',319,'existing_not_duplicated',117,'rows',202,'geonames_crosschecked',true),clock_timestamp()),('v3370_cj_discovery',true,jsonb_build_object('AU_records',170,'AU_selected',7,'MX_records',86,'MX_selected',0,'ID_records',31,'ID_selected',0,'country_target_is_city_serviceability_proof',false),clock_timestamp()),('v3370_au_cj_routes',exists(select 1 from public.nexus_v3370_cj_placement_policy where route_enabled and evidence_expires_at>clock_timestamp()),jsonb_build_object('requires_fresh_encrypted_payload',true),clock_timestamp()),('v3370_city_publication',false,jsonb_build_object('city_pages_published',false,'seo_indexing_enabled',false,'reason','unique useful landing content and human click endpoint are not approved'),clock_timestamp())on conflict(capability)do update set enabled=excluded.enabled,evidence=excluded.evidence,checked_at=excluded.checked_at;
do $assert$ declare b record;a record;s jsonb;persistence "char";begin select * into b from nexus_v3370_catalog_baseline;select(select count(*)from public.ads)ads_rows,(select count(*)from public.ads where active)active_ads_rows,(select count(*)from public.nexus_v370_keyword_source)keyword_rows,(select count(*)from public.nexus_v380_keyword_vectors)vector_rows into a;if row(b.ads_rows,b.active_ads_rows,b.keyword_rows,b.vector_rows)is distinct from row(a.ads_rows,a.active_ads_rows,a.keyword_rows,a.vector_rows)then raise exception 'v3370 protected catalogs changed';end if;if a.keyword_rows<>17605 then raise exception 'v3370 canonical keyword count';end if;if(select count(*)from public.nexus_v3370_city_delta)<>202 or(select count(*)from public.nexus_v3370_city_delta where routing_eligible)<>199 then raise exception 'v3370 city counts';end if;if(select count(*)from public.nexus_v3370_cj_placement_policy)<>7 then raise exception 'v3370 policy count';end if;if exists(select 1 from information_schema.columns where table_schema='public'and table_name='nexus_v3370_cj_placement_policy'and column_name in('affiliate_url','click_url','tracking_url','pid','token'))then raise exception 'v3370 plaintext column';end if;select relpersistence into persistence from pg_class where oid='public.nexus_v3370_city_delta'::regclass;if persistence<>'p'::"char"then raise exception 'v3370 city not LOGGED';end if;select relpersistence into persistence from pg_class where oid='public.nexus_v3370_cj_placement_policy'::regclass;if persistence<>'p'::"char"then raise exception 'v3370 policy not LOGGED';end if;if has_table_privilege('anon','public.nexus_v3370_city_delta','select')or has_table_privilege('authenticated','public.nexus_v3370_city_delta','select')or has_table_privilege('service_role','public.nexus_v3370_city_delta','select')then raise exception 'v3370 city ACL';end if;if has_function_privilege('anon','public.nexus_v3370_resolve_city(jsonb,text,text,text,text,boolean)','execute')or not has_function_privilege('service_role','public.nexus_v3370_resolve_city(jsonb,text,text,text,text,boolean)','execute')then raise exception 'v3370 resolver ACL';end if;if exists(select 1 from cron.job where jobid in(15,16,64)and active)then raise exception 'v3370 protected jobs activated';end if;s:=public.nexus_v3370_operator_status();if(s#>>'{city_delta,rows}')::int<>202 or(s#>>'{cj,au_policy_rows}')::int<>7 then raise exception 'v3370 status';end if;end $assert$;
commit;
